class Solution {
public:
    int countHomogenous(string s) {
        const long long MOD = 1000000007LL;
        long long ans = 0;
        int n = (int)s.size();
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && s[j] == s[i]) {
                j++;
            }
            long long k = (long long)(j - i);
            ans = (ans + k * (k + 1LL) / 2LL) % MOD;
            i = j;
        }
        return (int)ans;
    }
};
